import{_ as u,a0 as a,w as i,s,ao as d,I as o,x as e,a1 as r,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"怎樣打開64位 Ubuntu 的32位支持功能 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣打開64位 Ubuntu 的32位支持功能 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣打開64位 Ubuntu 的32位支持功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣打開64位 Ubuntu 的32位支持功能 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/How to enable 32-bit support for 64-bit Ubuntu 13.10 or greater","title":"怎樣打開64位 Ubuntu 的32位支持功能","tag":"201404","desc":""},"relativePath":"201404/How to enable 32-bit support for 64-bit Ubuntu 13.10 or greater.md","filePath":"[post].md"}'),b={name:"201404/How to enable 32-bit support for 64-bit Ubuntu 13.10 or greater.md"};function l(m,t,f,T,g,_){const p=a("Link");return i(),s("div",null,[t[11]||(t[11]=d(`<h1 id="怎樣打開64位-ubuntu-的32位支持功能" tabindex="-1">怎樣打開64位 Ubuntu 的32位支持功能 <a class="header-anchor" href="#怎樣打開64位-ubuntu-的32位支持功能" aria-label="Permalink to “怎樣打開64位 Ubuntu 的32位支持功能”">​</a></h1><p>大多數使用基於 Ubuntu/Debian 的發行版的人都更傾向於選擇64位的系統，對吧？這是因為64位的系統能夠充分發揮你的硬件的全部性能， 它使你能夠在更緊張的內存資源下使用更復雜的軟件，而且是真的快速使用，不必每次做一件小事都要等上許久。現在，32位僅有一個優點，那就是沒有太多兼容性上的問題。每次JAVA更新都很讓人很困惑，因為大多數用户都不能獲得需要的庫文件。在過去，很多別的軟件和驅動也沒有64位版。</p><p>因此，如果現在你有一個64位架構的系統，而且你可以使用之前的支持：包括驅動、64位版本和任何一個你需要的軟件。這樣就避免了所有的問題，對吧？現在有一個讓你可以在64位系統中使用32位軟件的方法，爽嗎？就在你讀了這篇文章然後照着做了之後就可以了。如果你有一個13.10或更高版本的Ubuntu/Debian，你需要安裝一個叫做 ia32-libs 的基礎包。現在，這個包已經被廢棄了，所以你必須手工安裝。</p><p>下面的命令可以在 Ubuntu/Debian 13.10 或更高的發行版上運行。</p><p>###第一步: 確認你有一個64位架構的內核</p><p>你可以打開終端然後輸入：</p><pre><code>dpkg --print-architecture
</code></pre><p>你將會看到像下面這樣的內容:</p><pre><code>amd64
</code></pre><p>這説明着你已經擁有了64位架構內核。</p><p>###第二步: 確認你打開了多架構支持功能</p><p>(多架構支持可以讓你在有64位庫的情況下使用32位庫。)</p><p>輸入:</p><pre><code>dpkg --print-foreign-architectures
</code></pre><p>輸出是:</p><pre><code>i386
</code></pre><p>如果你還沒有多架構支持你需要打開它。</p><p>另一種第二步: 打開多架構支持。</p><p>輸入:</p><pre><code>sudo dpkg --add-architecture i386

sudo apt -get update
</code></pre><p>然後就會開始下載更新然後運行。</p><p>之後你需要輸入:</p><pre><code>sudo apt-get dist-upgrade
</code></pre><p>它會檢查你已經擁有的庫文件是否有更新的版本。</p><p>若果然有的話，它會問你是否需要更新(y/n)。</p><p>如此這般，你就已經成功地為你的64位系統安裝了32位支持了。</p><hr>`,27)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),r(p,{href:"http://www.unixmen.com/enable-32-bit-support-64-bit-ubuntu-13-10-greater/"},{default:n(()=>[...t[0]||(t[0]=[e("http://www.unixmen.com/enable-32-bit-support-64-bit-ubuntu-13-10-greater/",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=e("譯者：",-1)),r(p,{href:"https://github.com/crowner"},{default:n(()=>[...t[2]||(t[2]=[e("crowner",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),r(p,{href:"https://github.com/wxy"},{default:n(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),r(p,{href:"http://linux.cn/"},{default:n(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const U=u(b,[["render",l]]);export{C as __pageData,U as default};
